python3 << 'EOF'
import json

with open('/app/benchmark/source_data.json') as f:
    data = json.load(f)

# Calculate decline rates for top improvers
mmr = data['maternal_mortality_timeseries']['data']
countries = {}
for row in mmr:
    c = row['country']
    if c not in countries:
        countries[c] = {}
    countries[c][row['year']] = row['mmr']

print("Country | 2005 | 2021 | Decline | % Decline")
for c, vals in countries.items():
    start = vals[2005]
    end = vals[2021]
    decline = start - end
    pct = decline / start * 100
    print(f"{c:12s} | {start:4d} | {end:4d} | {decline:4d} | {pct:.1f}%")

print("\n--- Rural-Urban Gap ---")
gap = data['rural_urban_mmr_gap']['data']
gaps = {}
for row in gap:
    c = row['country']
    if c not in gaps:
        gaps[c] = {}
    gaps[c][row['setting']] = row['mmr']
for c in gaps:
    urban = gaps[c]['urban']
    rural = gaps[c]['rural']
    print(f"{c:12s}: urban={urban}, rural={rural}, gap={rural-urban}")

print("\n--- Midwife Coverage ---")
mid = data['midwife_coverage']['data']
midw = {}
for row in mid:
    c = row['country']
    if c not in midw:
        midw[c] = {}
    midw[c][row['period']] = row['skilled_birth_attendant_pct']
for c in midw:
    early = midw[c]['2008-2012']
    late = midw[c]['2018-2021']
    print(f"{c:12s}: {early}% -> {late}% (change: +{late-early})")
EOF
